func jsonStr(s string) string {
	b := []byte{'"'}
	for _, r := range s {
		switch {
		case r == '"' || r == '\\':
			b = append(b, '\\', byte(r))
		case r < 32:
			b = append(b, []byte(fmt.Sprintf("\\u%04x", r))...)
		default:
			b = append(b, []byte(string(r))...)
		}
	}
	return string(append(b, '"'))
}

